<?php
$storeProductMode=true;
$productSection=in_array($_GET['product_section']??'', ['hpp','harga','stok'],true)?$_GET['product_section']:'hpp';
if($productSection==='stok'){require (dirname(__DIR__, 4) . '/app/Modules/Marketplace/Views/marketplace_store_stock.php');return;}
$globalFilters=['date_start'=>'','date_end'=>'','search'=>trim((string)($_GET['product_search']??'')),'product_status'=>trim((string)($_GET['product_status']??''))];
$catalogData=(new MarketplaceCatalogService())->listingForStore($activeStoreId,$globalFilters);
$query=static fn(array $changes=[]):string=>http_build_query(array_replace(['store'=>$activeStoreId,'tab'=>'produk','product_section'=>$productSection,'product_search'=>$globalFilters['search'],'product_status'=>$globalFilters['product_status']],$changes));
$timestamps=[];foreach($catalogData['products'] as $product)foreach($product['variants'] as $variant)if(!empty($variant['source_updated_at']))$timestamps[]=$variant['source_updated_at'];
$updated=$timestamps?max($timestamps):null;
$canSyncProducts=!empty($activeStore['is_connection_verified'])&&in_array($activeStore['platform'],['TikTok Shop','Shopee'],true)&&preg_match('/OWNER|ADMIN/i',(string)($_SESSION['role']??''));
?>
<section class="space-y-5" aria-labelledby="store-products-title">
 <header class="flex flex-wrap items-center justify-between gap-4"><div><p class="text-xs text-slate-500 mb-1"><?= htmlspecialchars($activeStore['platform']) ?> · <?= htmlspecialchars($activeStore['store_name']) ?></p><h1 id="store-products-title" class="text-2xl font-extrabold text-slate-900">Produk Toko</h1><p class="text-xs text-slate-500 mt-2">Kelola katalog produk dan varian toko ini.</p></div><div class="flex gap-2"><?php if($canSyncProducts): ?><button type="button" data-sync-catalog data-csrf="<?= htmlspecialchars(Workspace::csrf(),ENT_QUOTES) ?>" onclick="syncStoreCatalog(<?= htmlspecialchars(json_encode($activeStoreId),ENT_QUOTES,'UTF-8') ?>)" class="rounded-xl bg-emerald-600 text-white px-4 py-2 text-xs font-bold">Sinkronisasi Produk</button><?php endif; ?><a href="?<?= htmlspecialchars($query()) ?>" class="border rounded-xl bg-white px-4 py-2 text-xs font-bold">↻ Muat ulang</a></div></header>
 <div class="rounded-xl border border-blue-100 bg-blue-50 p-4 text-xs text-blue-900">Sumber: API <?= htmlspecialchars($activeStore['platform']) ?> · <?= $updated?'Pembaruan data sumber: '.htmlspecialchars($updated).' WIB':'Katalog API belum tersedia.' ?> <span class="block mt-1">Halaman menampilkan katalog terakhir yang tersimpan dari toko ini.</span><?php if(empty($activeStore['is_connection_verified'])): ?><p class="mt-2 text-amber-800">Koneksi API toko belum terverifikasi. <a class="font-bold underline" href="marketplace.php?tab=pengaturan&amp;peng_sub=integrasi">Buka Integrasi API</a> untuk menghubungkan toko <?= htmlspecialchars($activeStore['platform']) ?>.</p><?php endif; ?></div>
 <form method="get" class="flex flex-wrap gap-3 bg-white rounded-2xl border p-4 items-end"><input type="hidden" name="store" value="<?= htmlspecialchars($activeStoreId) ?>"><input type="hidden" name="tab" value="produk"><input type="hidden" name="product_section" value="<?= htmlspecialchars($productSection) ?>"><label class="flex-1 min-w-48 text-xs font-semibold">Cari produk / SKU / varian<input type="search" name="product_search" value="<?= htmlspecialchars($globalFilters['search']) ?>" placeholder="Nama produk, SKU, atau varian…" class="mt-2 w-full border rounded-xl px-3 py-2 font-normal"></label><label class="text-xs font-semibold">Status<select name="product_status" class="block mt-2 border rounded-xl px-3 py-2 font-normal"><option value="">Semua Status</option><?php foreach($catalogData['statuses'] as $status): ?><option value="<?= htmlspecialchars($status) ?>" <?= $globalFilters['product_status']===$status?'selected':'' ?>><?= htmlspecialchars($status) ?></option><?php endforeach; ?></select></label><button class="rounded-xl bg-brand-600 text-white text-xs font-bold px-4 py-2" type="submit">Terapkan</button><a class="border rounded-xl text-xs px-4 py-2" href="?<?= htmlspecialchars($query(['product_search'=>'','product_status'=>''])) ?>">Reset</a></form>
 <?php require (dirname(__DIR__, 4) . '/app/Modules/Marketplace/Views/marketplace_global_products.php'); ?>
</section>

